for item in data:
	for k, v in item.items():
		if k == 'modeName': item[k] = {"value": v, "style":{"backgroundColor": item['modeColor'] or '#FFFFFF', "color": system.kanoa.utilities.getContrastingColor(item['modeColor'] or '#FFFFFF'), "borderBottomRightRadius": '5px', "borderTopLeftRadius": '5px', "borderTopRightRadius": '5px', "borderBottomLeftRadius": '5px', "padding": '4px'}}

return data

customMethods.script:
#If there are mode event records associated with the link, then we will disable them. If there are no records, then we can delete the link
msgs = []	
for row in self.view.custom.assetModes.selectedData:
	if row['modeAssetLinkId'] is None: continue
	retVal, msg = system.kanoa.asset.unlinkAssetMode(row['modeAssetLinkId'])
	msgs.append(msg)
	if msg == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': '%s mode has been disabled as there are historical entries asssociated with it'%row['modeName']})
	elif retVal == 0: system.perspective.sendMessage('showFailerToast', {'message': '%s'%msg})

self.view.refreshBinding("custom.assetModes.data")

msgs = list(set(msgs))
if len(msgs) == 1:
	msgInfo = "Mode links have been" if len(self.view.custom.assetModes.selectedData) > 1 else "Mode link has been"
	system.perspective.sendMessage('showSuccessfulToast', {'message': '%s %s'%(msgInfo, msgs[0].lower())})
else:
	system.perspective.sendMessage('showWarningToast', {'message': '%s'%(msgs)})

return

system.perspective.print("enableAssetMode() called with %s"%enabled)
if self.view.custom.userAction.canUpdate:
	for item in self.view.custom.assetModes.selectedData:
		if enabled and not system.kanoa.utilities.getFieldValue('enabled', system.kanoa.asset.getModes({'modeId':item.modeId})):
			system.perspective.print('%s mode %s is disabled. Enable the mode to enable this mode for assets'%(item.modeName, item.modeId))
			system.perspective.sendMessage('showFailerToast', '%s mode is disabled. Enable the mode to enable this mode for assets'%item.modeName)
		else:
			system.kanoa.asset.enableModeAssetLink(item['modeAssetLinkId'], enabled)
else:
	system.perspective.print("no permission")
	system.perspective.sendMessage('showFailerToast', 'No permissions to update modes.')

self.view.refreshBinding("custom.assetModes.data")
return

retVal, response = system.kanoa.asset.deleteMode(modeId, self.view.custom.security.userId)
if response == 'Disabled': system.perspective.sendMessage('showWarningToast', {'message': 'Mode has been disabled as there are historical entries asssociated with this mode.'})
elif response == 'Deleted': system.perspective.sendMessage('showSuccessfulToast', {'message': 'Mode has been deleted.'})
else: system.perspective.sendMessage('showFailerToast', {'message': 'Mode has not been deleted. \n%s'%(response)})	

self.clearAssetModeSelection()
self.view.refreshBinding("custom.assetModes.data")

return
